12	export default async function DeployPage() {
13	  const user = await requireUser();
14	  // The active intro promo (Summer Sale etc.). payAndDeploy charges the promo
15	  // price on the first term (lib/order.ts), so the wizard must DISPLAY it too —
16	  // otherwise displayed ($8.99) ≠ charged ($6.29). Computed server-side so the
17	  // shown promo matches the one checkout applies.
18	  const promo = currentPromo(new Date());
19	  const [plans, images, sshKeys, nodes, capacity, freeIps] = await Promise.all([
20	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
21	    db.osTemplate.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { name: "asc" }] }),
22	    db.sshKey.findMany({ where: { userId: user.id }, select: { id: true, name: true, publicKey: true } }),
23	    db.node.findMany({ where: { enabled: true }, select: { id: true, name: true, publicIp: true } }),
24	    capacitySnapshot(),
25	    db.dedicatedIp.count({ where: { status: "FREE" } }),
26	  ]);
27	
28	  return (
29	    <div className="space-y-6">
30	      <PageHeader title="Deploy a server" sub="NVMe-backed KVM virtual machines, live in under two minutes." />
31	      {capacity.nearCapacity && (
32	        <div className="rounded-2xl border border-amber-500/30 bg-amber-500/10 px-4 py-3 text-sm text-amber-300">
33	          <span className="font-semibold">Host is filling up.</span> We&apos;re at{" "}
34	          {Math.round(capacity.ramUtilization * 100)}% of committed RAM. Larger plans may be briefly unavailable.
35	        </div>
36	      )}
37	      {plans.length === 0 || images.length === 0 ? (
38	        <EmptyState
39	          title="Deployments are temporarily unavailable"
40	          sub="No active plans or images are configured. Please check back soon or contact support."
41	        />
42	      ) : (
43	        <DeployWizard
44	          plans={plans.map((p) => ({
45	            id: p.id,
46	            name: p.name,
47	            cpuCores: p.cpuCores,
48	            ramMB: p.ramMB,
49	            diskGB: p.diskGB,
50	            bandwidthTB: p.bandwidthTB,
51	            priceCents: p.priceCents,
52	            storageTier: p.storageTier,
53	          }))}
54	          images={images.map((o) => ({
55	            id: o.id,
56	            slug: o.slug,
57	            name: o.name,
58	            category: o.category,
59	            family: o.family,
60	            version: o.version,
61	            logo: o.logo,
62	            minRamMB: o.minRamMB,
63	            minDiskGB: o.minDiskGB,
64	            licenseRequired: o.licenseRequired,
65	            featured: o.featured,
66	          }))}
67	          nodes={nodes}
68	          sshKeys={sshKeys.map((k) => ({ id: k.id, name: k.name }))}
69	          isAdmin={user.role === "ADMIN"}
70	          balanceCents={user.balanceCents}
71	          dedicatedIpAvailable={freeIps > 0}
72	          dedicatedIpPriceCents={await dedicatedIpMonthlyCents()}
73	          extraDiskPriceCentsPerGb={await extraDiskPerGbCents()}
74	          promoPercent={promo.discountPercent}
75	          promoLabel={promo.label}
76	        />
77	      )}
78	    </div>
79	  );
80	}
