40	/**
41	 * Claim exclusive responsibility for fulfilling `sessionId`.
42	 * Returns false when another caller already holds the claim — the UNIQUE index,
43	 * not a read-then-write check, is what makes this safe under concurrency.
44	 */
45	async function claim(sessionId: string, kind: string): Promise<boolean> {
46	  try {
47	    await db.fulfilledSession.create({ data: { stripeSessionId: sessionId, kind } });
48	    return true;
49	  } catch (e) {
50	    if ((e as { code?: string })?.code === "P2002") return false; // someone else has it
51	    throw e;
52	  }
53	}
54	
55	async function settle(sessionId: string, status: "DONE" | "FAILED", detail?: string) {
56	  await db.fulfilledSession
57	    .update({ where: { stripeSessionId: sessionId }, data: { status, detail: detail?.slice(0, 500) } })
58	    .catch(() => {});
59	}
