316	async function completeTransferIn(
317	  domain: { id: string; name: string; userId: string },
318	  rawStatus: string,
319	  owned: { expires?: Date; created?: Date } | null
320	) {
321	  const expiresAt = owned?.expires ?? new Date(Date.now() + TRANSFER_TERM_YEARS * 365 * DAY);
322	  const settled = await settleCompletedTransferIn({
323	    domainId: domain.id,
324	    transferStatus: rawStatus,
325	    registeredAt: owned?.created ?? new Date(),
326	    expiresAt,
327	  });
328	  if (!settled) return;
329	
330	  await db.auditLog.create({
331	    data: { userId: domain.userId, action: "domain.transfer_in.completed", detail: domain.name },
332	  });
333	  await db.notification.create({
334	    data: {
335	      userId: domain.userId,
336	      title: `${domain.name} transferred in successfully`,
337	      body: `It's now managed here and expires ${expiresAt.toISOString().slice(0, 10)} — the transfer added a year. DNS and auto-renew are ready to set up.`,
338	      href: `/dashboard/domains/${domain.id}`,
339	    },
340	  });
341	  console.log(`[billing] transfer-in completed for ${domain.name}`);
342	}
