385	/**
386	 * Enforcement for an unpaid volume past grace: detach only, never destroy.
387	 * An ATTACHED volume is flipped to DETACHED and a VOLUME_DETACH job is queued
388	 * (both in one transaction, so we never mark it detached without doing it).
389	 * The underlying disk — and every byte on it — is left intact.
390	 */
391	async function detachUnpaidVolume(
392	  volume: {
393	    id: string;
394	    userId: string;
395	    name: string;
396	    serverId: string | null;
397	    status: string;
398	    expiresAt: Date | null;
399	  },
400	  priceCents: number,
401	  now: Date
402	) {
403	  if (volume.status !== "ATTACHED") {
404	    // Nothing to detach (PENDING / already DETACHED) — just keep nagging.
405	    await notifyOnce(
406	      now,
407	      volume.userId,
408	      volume.name,
409	      "volume unpaid",
410	      `Volume "${volume.name}" is unpaid`,
411	      `This volume is overdue by ${money(priceCents)}/mo. Your data is retained, but the volume may be removed if it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))}. Top up to keep it.`,
412	      VOLUME_HREF
413	    );
414	    return;
415	  }
416	
417	  // Respect the one-in-flight-job guard so we don't collide with a user or
418	  // worker operation already running on that server; retry on the next sweep.
419	  if (volume.serverId) {
420	    const busy = await db.job.count({
421	      where: { serverId: volume.serverId, status: { in: ["QUEUED", "RUNNING"] } },
422	    });
423	    if (busy > 0) return;
424	  }
425	
426	  try {
427	    await db.$transaction(async (tx) => {
428	      const flipped = await tx.volume.updateMany({
429	        where: { id: volume.id, status: "ATTACHED" },
430	        data: { status: "DETACHED" },
431	      });
432	      if (flipped.count === 0) throw new AlreadyHandledError(`volume ${volume.id}`);
433	      await tx.job.create({
434	        data: { type: "VOLUME_DETACH", serverId: volume.serverId, payload: { volumeId: volume.id } },
435	      });
436	      await tx.auditLog.create({
437	        data: {
438	          userId: volume.userId,
439	          action: "billing.volume_detached_unpaid",
440	          detail: `volume ${volume.id} ${volume.name}`,
441	        },
442	      });
443	    });
444	  } catch (e) {
445	    if (e instanceof AlreadyHandledError) return;
446	    throw e;
447	  }
448	
449	  await notify(
450	    volume.userId,
451	    `Volume "${volume.name}" detached — payment overdue`,
452	    `We couldn't collect ${money(priceCents)} for this volume, so it was detached from your server. Nothing was deleted: all data on the volume is retained and re-attaches exactly as it was once you top up and renew. If it stays unpaid past ${ymd(reclaimAt(volume.expiresAt!))} the volume may be removed.`,
453	    VOLUME_HREF
454	  );
455	  console.log(`${LOG} detached unpaid volume ${volume.id} (${volume.name})`);
456	}
