1	/**
2	 * Pricing + renewal-period math for the recurring add-on products
3	 * (business email subscriptions and block-storage volumes).
4	 *
5	 * Deliberately PURE: no `db`, no I/O, no side effects — everything here is a
6	 * plain function over plain values so the renewal policy can be unit-tested
7	 * without a database. The worker sweep (`worker/product-renewals.ts`) owns all
8	 * the reads/writes and asks this module *what* should happen.
9	 *
10	 * Policy shape mirrors `worker/billing.ts` (VPS/domains) so customers see one
11	 * consistent billing behaviour across every product:
12	 *   warn before expiry -> expire -> grace period -> enforce (suspend / detach)
13	 */
14	
15	import { addMonths } from "./billing-terms";
16	
17	export const DAY_MS = 86_400_000;
18	
19	/** Read a positive integer from the environment, falling back on a default. */
20	export function envInt(name: string, fallback: number): number {
21	  const raw = process.env[name];
22	  const n = Number(raw);
23	  return raw !== undefined && Number.isFinite(n) && n >= 0 ? n : fallback;
24	}
