60	/** Amount charged to renew an email subscription for one plan term. */
61	export function emailRenewalCents(plan: { priceCents: number }): number {
62	  return Math.max(0, Math.round(plan.priceCents));
63	}
64	
65	/** Plan term in whole months, clamped to >= 1 so a bad row can't stall renewal. */
66	export function emailRenewalMonths(plan: { termMonths?: number | null }): number {
67	  const m = Math.round(Number(plan.termMonths ?? 1));
68	  return Number.isFinite(m) && m >= 1 ? m : 1;
69	}
70	
71	/** Amount charged to renew a volume for one month. */
72	export function volumeRenewalCents(volume: { priceCents: number }): number {
73	  return Math.max(0, Math.round(volume.priceCents));
74	}
75	
76	/**
77	 * The expiry a renewal should advance to.
78	 *
79	 * The base is `max(currentExpiry, now)`, so an item that has been expired for
80	 * months is brought forward to one full term from *today* with a single charge
81	 * rather than being back-billed for every missed period. This also guarantees
82	 * the new expiry is always strictly in the future, which is what makes the
83	 * sweep idempotent (the "due" query only selects `expiresAt < now`).
84	 */
85	export function nextExpiry(
86	  currentExpiry: Date | null | undefined,
87	  now: Date,
88	  months: number
89	): Date {
90	  const base = new Date(
91	    Math.max(currentExpiry ? currentExpiry.getTime() : now.getTime(), now.getTime())
92	  );
93	  return addMonths(base, Math.max(1, Math.round(months)));
94	}
